def solution(levels):
    rise_days = 0
    biggest = 0
    smallest = levels[1] - levels[0]
    prev = levels[0]
    for now in levels[1:]:
        change = now - prev
        if change > 0:
            rise_days += 1
        if change > biggest:
            biggest = change
        if change < smallest:
            smallest = change
        prev = now
    return [biggest, smallest, rise_days]

