    best = -21
    best_total = 0
    best_day = 0
    for s in range(len(temps) - k + 1):
        low = temps[0]
        total = 0
        for t in temps[s:s + k]:
            total += t
            if t < low:
                low = t
        if low > best or (low == best and total > best_total):
            best = low
            best_total = total
            best_day = s + 1
    return [best_day, best]

